-- ============================================================================
-- Carysil AI — move product images off WordPress (carysil.com/wp-content)
-- onto the Sanity CDN used by the new Next.js site.
--
-- 389 products. Each new URL was matched by product slug against the
-- Sanity `product` documents (main image, else first non-diagram gallery
-- photo — same rule the website uses) and checked to return HTTP 200.
--
-- Run in: Supabase Dashboard → SQL Editor → New query → Run
-- Safe to re-run: each row only updates while it still holds the old URL.
-- Rollback: UPDATE products p SET image_url = b.image_url
--           FROM products_image_url_backup_20261009 b WHERE b.id = p.id;
-- ============================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS products_image_url_backup_20261009 AS
SELECT id, image_url FROM products;

UPDATE products p
SET image_url = m.new_url, updated_at = NOW()
